v_wmma_scale_f32_16x16x128_f8f6f4 v[0:7], v[8:15], v[16:31], v[40:47], 5, 5 matrix_a_fmt:MATRIX_FMT_FP4 matrix_b_fmt:MATRIX_FMT_BF8
